CREATE TABLE IF NOT EXISTS Users (Id INTEGER PRIMARY KEY AUTOINCREMENT, Username TEXT NOT NULL COLLATE NOCASE UNIQUE, PasswordHash TEXT NOT NULL, IsActive INTEGER NOT NULL DEFAULT 1, CreatedUtc TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS Sessions (Token TEXT PRIMARY KEY, UserId INTEGER NOT NULL, ExpiresUtc TEXT NOT NULL, CreatedUtc TEXT NOT NULL, FOREIGN KEY(UserId) REFERENCES Users(Id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS IX_Sessions_ExpiresUtc ON Sessions(ExpiresUtc);
